#include <iostream>
#include <algorithm>
#include <cstdlib>

using namespace std;

void Sort(int left, int right, int* mas) {
    int l = left;
    int r = right;
    int pivot = mas[left + (right - left) / 2];

    while (l <= r) {
        while (mas[l] < pivot)
            ++l;
        while (mas[r] > pivot)
            --r;

        if (l <= r) {
            swap(mas[l], mas[r]);
            ++l;
            --r;
        }
    }

    if (left < r)
        Sort(left, r, mas);
    if (l < right)
        Sort(l, right, mas);
}

int main() {
    int n;
    cin >> n;

    int* a = new int[n];
    long long sum = 0;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    if (n > 0)
        Sort(0, n - 1, a);

    for (int i = 0; i + 1 < n; i += 2) {
        if (a[i] != a[i + 1])
            sum += llabs(static_cast<long long>(a[i]) - a[i + 1]);
    }

    cout << sum;
    delete[] a;

    return 0;
}

